import android.text.Editable;
import android.text.method.PasswordTransformationMethod;
import android.widget.EditText;

import java.util.Arrays;

public class EditTextHelper {
    private EditTextHelper() {
    }

    /**
     * Toggles the visibility of the text in the given password EditText, while
     * preserving the position of the cursor.
     */
    public static void setEditTextPasswordVisibility(EditText text, boolean visible) {
        int selectionStart = text.getSelectionStart();
        int selectionEnd = text.getSelectionEnd();
        text.setTransformationMethod(visible ? null : new PasswordTransformationMethod());
        if (selectionStart >= 0 && selectionEnd >= 0) {
            text.setSelection(selectionStart, selectionEnd);
        }
    }

